// n8n Code node: "Validate payload"
// The parse-csv Lambda POSTs {batch_id, row_count}. Reject anything that is not a UUID so a
// malformed or hostile request can never reach the SQL stages. (Webhook v2 nests the JSON
// under `body`.)
const raw = $input.first().json;
const b = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const id = String(b.batch_id || '').trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id)) {
  throw new Error(`invalid batch_id in webhook payload: ${JSON.stringify(b.batch_id)}`);
}
return [{ json: { batch_id: id, row_count: Number(b.row_count) || 0, received_at: new Date().toISOString() } }];

// n8n Code node: "Stage 0: reconcile lenders"  (mode: Run Once for All Items)
//
// Input : fresh loan_products rows (one item each).
// Output: ONE item per lender. The same lender shows up on several sites with different
//         (sometimes conflicting) thresholds; matching a user against both would list the
//         lender twice in an email, and the strict/lenient disagreement has no right answer.
//         We keep the single most authoritative record and record what was dropped.
//
// Authority order: the lender's own site > the record that states more criteria >
// aggregator rank (Paisabazaar before BankBazaar) > lower advertised rate.

const OFFICIAL = new Set(['bajajfinserv']);
const SOURCE_RANK = { bajajfinserv: 0, paisabazaar: 1, bankbazaar: 2 };
const STOP = new Set(['personal', 'loan', 'bank', 'of', 'india', 'finance', 'finserv', 'first',
                      'mahindra', 'capital', 'ltd', 'limited', 'and']);

// "HDFC Bank Personal Loan" / "HDFC Personal Loan" -> "hdfc"; "Bank of India" -> "bank of india"
function lenderKey(name) {
  const norm = name.toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  const core = norm.split(' ').filter((t) => !STOP.has(t));
  return core.length ? core.join(' ') : norm.replace(/\s*personal loan$/, '');
}

function completeness(p) {
  let n = 0;
  for (const k of ['min_income', 'min_credit_score', 'min_age', 'max_age']) if (p[k] !== null && p[k] !== undefined) n++;
  return n + (Array.isArray(p.eligibility_rules) ? p.eligibility_rules.length * 0.1 : 0);
}

function better(a, b) {
  const oa = OFFICIAL.has(a.source_site), ob = OFFICIAL.has(b.source_site);
  if (oa !== ob) return oa;
  const ca = completeness(a), cb = completeness(b);
  if (ca !== cb) return ca > cb;
  const ra = SOURCE_RANK[a.source_site] ?? 9, rb = SOURCE_RANK[b.source_site] ?? 9;
  if (ra !== rb) return ra < rb;
  return Number(a.interest_rate) <= Number(b.interest_rate);
}

const groups = new Map();
for (const { json: p } of $input.all()) {
  const key = lenderKey(p.product_name);
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(p);
}

const out = [];
for (const [key, rows] of groups) {
  let best = rows[0];
  for (const r of rows.slice(1)) if (better(r, best)) best = r;
  out.push({
    json: {
      ...best,
      lender_key: key,
      reconciled_from: rows.map((r) => `${r.source_site}#${r.product_id}`),
      products_in_group: rows.length,
    },
  });
}
console.log(`reconciled ${$input.all().length} products into ${out.length} lenders`);
return out.sort((a, b) => a.json.lender_key.localeCompare(b.json.lender_key));

// n8n Code node: "Collect canonical product ids"  (runs once)
// Folds the reconciled lenders into the single item the SQL stages need.
const lenders = $input.all().map((i) => i.json);
return [{
  json: {
    batch_id: $('Validate payload').first().json.batch_id,
    product_ids: lenders.map((l) => l.product_id),
    products_fresh: $('Load fresh products').all().length,
    products_canonical: lenders.length,
    merged_groups: lenders.filter((l) => l.products_in_group > 1).length,
  },
}];

// n8n Code node: "Build review prompt"
// One item per (product x employment-type) segment. The prompt carries the lender's fuzzy
// criteria plus the segment's real ranges from the database, so the model judges this
// segment rather than guessing about a generic applicant.
const SYSTEM = "You help explain personal-loan eligibility to customers. A group of applicants has ALREADY been checked against the lender's numeric rules (monthly income, credit score, age) and the employment types the lender accepts. Your job is only to say how confident the match is and, when relevant, what the customer still needs to check.

You receive: a summary of one applicant segment from a customer database (employment type, plus ranges of monthly income in INR, credit score and age), the employment types the lender's structured data accepts, the lender's qualitative requirements (a summary) and the lender's original source text (ground truth).

IMPORTANT: the database contains ONLY employment type, monthly income, credit score and age. It has NO information about work experience, employer or employer category, city, education, profession, an existing bank account or relationship, or nationality.

You NEVER reject applicants. Numeric limits and accepted employment types are already decided; do not re-judge them.

Return ONLY a JSON object: {"verdict":"conditional","caveat":"..."}
- verdict "eligible": the qualitative requirements place no extra conditions on this segment.
- verdict "conditional": the segment may qualify, but it depends on facts missing from the database (work experience, employer type, city, profession, existing bank relationship, nationality, ...). Name the most important ones in the caveat.
- caveat: one plain-English sentence addressed to the customer, at most 140 characters, no jargon; null when the verdict is "eligible". Only state conditions that appear in the lender's text; never invent a threshold.";
const inr = (n) => '₹' + Number(n).toLocaleString('en-IN');

return $input.all().map(({ json: s }) => ({
  json: {
    ...s,
    system_prompt: SYSTEM,
    user_prompt:
      `Lender product: ${s.product_name}
` +
      `Applicant segment: ${s.employment_type}, ${s.candidates} applicants
` +
      `Monthly income: ${inr(s.income_min)} to ${inr(s.income_max)} (median ${inr(s.income_median)})
` +
      `Credit score: ${s.score_min} to ${s.score_max}
` +
      `Age: ${s.age_min} to ${s.age_max}

` +
      `Employment types the lender's structured data accepts: ${s.accepted_types || 'not stated'}

` +
      `Lender's qualitative requirements (summary):
${s.qualitative_criteria_text}

` +
      `Lender's source eligibility text (ground truth):
${s.source_text || '(not available)'}`,
  },
}));

// n8n Code node: "Validate <provider> review"  (stamped per provider by build_workflows.py)
// Turns a raw LLM response into {valid, verdict, caveat}. Anything that is not exactly one of
// the three verdicts is invalid, which routes the item to the Gemini fallback (or, after
// Gemini, leaves the segment unreviewed => treated as 'conditional' in Stage 4).
const PROVIDER = 'groq'; // 'groq' | 'gemini'
// The reviewer may only grade a segment 'eligible' or 'conditional'. An LLM veto proved
// unreliable on real data (it applied a salaried income floor to self-employed applicants,
// excluded employment types the lender accepts, and flipped between runs), so 'ineligible'
// is demoted to 'conditional': numeric rules and employment types were already verified
// exactly in Stages 1-2, and the LLM must not silently remove a user on its own judgement.
const VERDICTS = ['eligible', 'conditional', 'ineligible'];

function responseText(res) {
  if (!res || res.error) return null;
  if (PROVIDER === 'groq') return (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || null;
  const parts = res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts;
  return parts ? parts.map((p) => p.text || '').join('') : null;
}
function parseJson(t) {
  if (!t) return null;
  t = t.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) { /* fall through */ }
  const m = t.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) { /* give up */ } }
  return null;
}

return $input.all().map((item, i) => {
  const original = $('Build review prompt').itemMatching(i).json;
  const fail = (why) => ({ json: { ...original, valid: false, extraction_status: `invalid_${PROVIDER}`, llm_error: why } });
  if (item.json && item.json.error) return fail(`request failed: ${JSON.stringify(item.json.error).slice(0, 160)}`);

  const parsed = parseJson(responseText(item.json));
  let verdict = parsed && typeof parsed.verdict === 'string' ? parsed.verdict.trim().toLowerCase() : null;
  if (!VERDICTS.includes(verdict)) return fail('response had no valid verdict');
  const demoted = verdict === 'ineligible';
  if (demoted) verdict = 'conditional';

  let caveat = typeof parsed.caveat === 'string' ? parsed.caveat.trim() : null;
  if (caveat && /^(null|none|n\/a)$/i.test(caveat)) caveat = null;
  if (caveat && caveat.length > 160) caveat = caveat.slice(0, 157) + '...';
  if (verdict === 'eligible') caveat = null;
  if (demoted && !caveat) caveat = 'The lender has extra requirements we could not check.';

  return { json: { ...original, valid: true, extraction_status: `llm_${PROVIDER}`, verdict, caveat, demoted_ineligible: demoted } };
});

